var monthNamesByLanguage = map[string][12]string{
	English: {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"},
	Swahili: {"Jan", "Feb", "Mac", "Apr", "Mei", "Jun", "Jul", "Ago", "Sep", "Okt", "Nov", "Des"},
}

func Label(language string, key string, replacements ...string) string {
	labelText, isKnown := labelsByLanguage[ResolveLanguage(language)][key]
	if !isKnown {
		labelText = labelsByLanguage[English][key]
	}
	return strings.NewReplacer(replacements...).Replace(labelText)
}

func MonthYear(language string, moment time.Time) string {
	return monthName(language, moment.Month()) + " " + moment.Format("2006")
}

func monthName(language string, month time.Month) string {
	return monthNamesByLanguage[ResolveLanguage(language)][month-1]
}
